from .section_executor import SectionExecutor
from .section_radio import SectionRadio
from .section_tgr import SectionTgr
from .section_ip_configuration import SectionIpConfiguration
from .section_ctrl import SectionCtrl
from .section_enb import SectionEnb
from .section_sector import SectionSector
from ..config_file_generic import TextBasedConfigFile
from ..utils.logger import logger


class CUS(TextBasedConfigFile):

    def __init__(self, filename='cus.ini', section_separator='\n\n'):
        logger.info("Generating CUS.ini")
        super().__init__(filename, section_separator)
        self._sections = [
            SectionExecutor(),
            SectionEnb(),
            SectionIpConfiguration(),
            SectionCtrl(),
            SectionSector(),
            SectionRadio(),
            SectionTgr()
        ]
